'use strict';
const fs = require('fs');
const path = require('path');

const dir = __dirname;
const readNum = (name) => {
  const p = path.join(dir, name);
  if (!fs.existsSync(p)) throw new Error(`${name} is missing`);
  const raw = fs.readFileSync(p, 'utf8').trim();
  if (raw === '') throw new Error(`${name} is empty`);
  const n = Number(raw);
  if (!Number.isFinite(n)) throw new Error(`${name} is not numeric: ${JSON.stringify(raw)}`);
  return n;
};

const checks = [];
const check = (label, actual, expected) => {
  const ok = actual === expected;
  checks.push({ label, actual, expected, ok });
  if (!ok) throw new Error(`${label} failed: expected ${expected}, got ${actual}`);
};

// Read every saved stage from disk and re-derive the chain from those files.
const seed = readNum('seed.txt');
const stage1 = readNum('stage1.txt');
const stage2 = readNum('stage2.txt');
const stage3 = readNum('stage3.txt');

check('stage1 == seed + 2', stage1, seed + 2);
check('stage2 == stage1 * stage1', stage2, stage1 * stage1);
check('stage3 == stage2 - 4', stage3, stage2 - 4);

const answer = { stage1, stage2, stage3 };
fs.writeFileSync(path.join(dir, 'answer.json'), JSON.stringify(answer, null, 2) + '\n');

// Read answer.json back and verify keys/values are numeric and match the saved files.
const saved = JSON.parse(fs.readFileSync(path.join(dir, 'answer.json'), 'utf8'));
const keys = Object.keys(saved).sort();
check('answer.json keys', keys.join(','), 'stage1,stage2,stage3');
for (const k of ['stage1', 'stage2', 'stage3']) {
  check(`answer.json.${k} is number`, typeof saved[k], 'number');
  check(`answer.json.${k} equals ${k}.txt`, saved[k], readNum(`${k}.txt`));
}

for (const c of checks) console.log(`PASS ${c.label} (${c.actual})`);
console.log('ALL CHECKS PASSED:', checks.length);
console.log('answer.json =', JSON.stringify(saved));

