const readRaw = f => { if (!fs.existsSync(f)) throw new Error(f + ' missing'); return fs.readFileSync(f, 'utf8'); };

// 1. Files exist
for (const f of ['seed.txt','stage1.txt','stage2.txt','stage3.txt','answer.json']) t('exists ' + f, fs.existsSync(f));

// 2. Stage files are plain decimal integers, as the chain requires
for (const f of ['seed.txt','stage1.txt','stage2.txt','stage3.txt']) {
  const raw = readRaw(f);
  t(f + ' is plain integer text', /^-?\d+$/.test(raw.trim()) && raw.trim().length > 0, JSON.stringify(raw));
}

// 3. Recompute chain independently from the saved files
const n = f => Number(readRaw(f).trim());
const seed = n('seed.txt'), s1 = n('stage1.txt'), s2 = n('stage2.txt'), s3 = n('stage3.txt');
t('stage1 == seed + 2', s1 === seed + 2, `${seed}+2=${seed+2} vs ${s1}`);
t('stage2 == stage1^2', s2 === s1 * s1, `${s1}^2=${s1*s1} vs ${s2}`);
t('stage3 == stage2 - 4', s3 === s2 - 4, `${s2}-4=${s2-4} vs ${s3}`);

// 4. answer.json is valid JSON with exactly the required numeric keys and no extras
const rawA = readRaw('answer.json');
let a;
try { a = JSON.parse(rawA); t('answer.json parses', true); } catch (e) { t('answer.json parses', false, e.message); }
t('answer.json is object', a && typeof a === 'object' && !Array.isArray(a), Array.isArray(a) ? 'array' : typeof a);
const keys = Object.keys(a || {}).sort().join(',');
t('answer.json keys exactly stage1,stage2,stage3', keys === 'stage1,stage2,stage3', keys);
t('answer.json.stage1 numeric == stage1.txt', typeof a.stage1 === 'number' && a.stage1 === s1, `${typeof a.stage1} ${a.stage1} vs ${s1}`);
t('answer.json.stage2 numeric == stage2.txt', typeof a.stage2 === 'number' && a.stage2 === s2, `${typeof a.stage2} ${a.stage2} vs ${s2}`);
t('answer.json.stage3 numeric == stage3.txt', typeof a.stage3 === 'number' && a.stage3 === s3, `${typeof a.stage3} ${a.stage3} vs ${s3}`);

// 5. Content integrity fingerprints
const crypto = require('crypto');
for (const f of ['seed.txt','stage1.txt','stage2.txt','stage3.txt','answer.json'])
  console.log('sha256 ' + f + ' ' + crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex'));

console.log('FAILURES=' + fails);
process.exit(fails ? 1 : 0);
EOF
